const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
        AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
        ShadingType, PageOrientation } = require('docx');
const fs = require('fs');

// Colors (Luxora feel: black, warm neutrals, gold accent)
const GOLD = "B8935A";
const DARK = "1A1A1A";
const LIGHT_BG = "F5F1EA";
const BORDER = "D4C9B8";

const border = { style: BorderStyle.SINGLE, size: 4, color: BORDER };
const borders = { top: border, bottom: border, left: border, right: border };

// Helper: table row
const row = (label, boost, luxora, isHeader = false) => {
  const shade = isHeader ? { fill: DARK, type: ShadingType.CLEAR } : undefined;
  const textColor = isHeader ? "FFFFFF" : DARK;
  const bold = isHeader;

  const mkCell = (text, width, align = AlignmentType.LEFT) =>
    new TableCell({
      borders,
      width: { size: width, type: WidthType.DXA },
      shading: shade,
      margins: { top: 100, bottom: 100, left: 140, right: 140 },
      children: [new Paragraph({
        alignment: align,
        children: [new TextRun({ text, bold, color: textColor, size: 18, font: "Calibri" })]
      })]
    });

  return new TableRow({
    children: [
      mkCell(label, 2880),
      mkCell(boost, 3240, AlignmentType.LEFT),
      mkCell(luxora, 3240, AlignmentType.LEFT)
    ]
  });
};

const comparisonTable = new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [2880, 3240, 3240],
  rows: [
    row("", "INJECTABLE BOOST", "THE LUXORA COLLECTIVE", true),
    row("Core Focus", "Lead generation + automation", "Full revenue ecosystem: acquisition, conversion, and retention"),
    row("Approach", "Done-for-you marketing engine", "Hybrid done-with-you and done-for-you growth system"),
    row("Starting Point", "Drive more leads in", "Fix the leaks first, then scale with precision"),
    row("Marketing", "Paid ads and automation", "Meta and IG ads, retargeting, premium offer strategy"),
    row("Sales Process", "Minimal", "Consult optimization and staff sales training"),
    row("Follow-Up", "Automated nurture", "12 to 15 touchpoint AI and human hybrid"),
    row("CRM", "Included", "Custom CRM with full pipeline visibility"),
    row("Retention and LTV", "Light", "Core pillar: memberships, packages, LTV frameworks"),
    row("Internal Systems", "Minimal", "Staff training, ops, and utilization"),
    row("Guarantee", "Performance-based campaigns", "2x Lifetime Client Value guarantee, we work for free until you hit it"),
  ]
});

// Divider paragraph
const divider = () => new Paragraph({
  spacing: { before: 120, after: 120 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 1 } },
  children: [new TextRun({ text: "" })]
});

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Calibri", size: 20, color: DARK } } },
  },
  numbering: {
    config: [{
      reference: "bullets",
      levels: [{
        level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 360, hanging: 220 } } }
      }]
    }]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1080, bottom: 1080, left: 1080 }
      }
    },
    children: [
      // Header
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 40 },
        children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 20, color: GOLD, font: "Calibri", characterSpacing: 60 })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 200 },
        children: [new TextRun({ text: "Premium Revenue Growth for Independent Med Spas", italics: true, size: 18, color: DARK, font: "Calibri" })]
      }),

      // Title
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 80 },
        children: [new TextRun({ text: "Injectable Boost vs. Luxora", bold: true, size: 36, color: DARK, font: "Calibri" })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 240 },
        children: [new TextRun({ text: "A side by side look at what each partner actually does for your business", size: 20, color: "555555", font: "Calibri" })]
      }),

      // Intro positioning
      new Paragraph({
        spacing: { after: 180 },
        children: [
          new TextRun({ text: "The short version: ", bold: true, size: 20, font: "Calibri" }),
          new TextRun({ text: "Injectable Boost is fuel. Luxora is the engine, the fuel, and the navigation system. If your goal is more leads in the door, a marketing-only partner can help. If your goal is sustainable revenue growth with higher client value and a business that scales without you in every transaction, that is what we build.", size: 20, font: "Calibri" })
        ]
      }),

      // Comparison table
      comparisonTable,

      // Spacer
      new Paragraph({ spacing: { before: 200 }, children: [new TextRun({ text: "" })] }),

      // Two column style sections using two headers side by side
      new Paragraph({
        spacing: { after: 100 },
        children: [new TextRun({ text: "Where Injectable Boost Fits", bold: true, size: 22, color: GOLD, font: "Calibri" })]
      }),
      new Paragraph({
        spacing: { after: 80 },
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text: "You want fast lead volume with minimal involvement", size: 19, font: "Calibri" })]
      }),
      new Paragraph({
        spacing: { after: 80 },
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text: "You are comfortable with heavy automation handling client communication", size: 19, font: "Calibri" })]
      }),
      new Paragraph({
        spacing: { after: 180 },
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text: "Your internal systems, sales process, and retention are already dialed in", size: 19, font: "Calibri" })]
      }),

      new Paragraph({
        spacing: { after: 100 },
        children: [new TextRun({ text: "Where Luxora Fits", bold: true, size: 22, color: GOLD, font: "Calibri" })]
      }),
      new Paragraph({
        spacing: { after: 80 },
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text: "You already have staff, equipment, and marketing spend in place", size: 19, font: "Calibri" })]
      }),
      new Paragraph({
        spacing: { after: 80 },
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text: "You sense revenue is slipping through the cracks and want to know where", size: 19, font: "Calibri" })]
      }),
      new Paragraph({
        spacing: { after: 80 },
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text: "You want predictable revenue, higher client value, and a business that scales", size: 19, font: "Calibri" })]
      }),
      new Paragraph({
        spacing: { after: 240 },
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text: "You want knowledge transfer, not long term dependence on an agency", size: 19, font: "Calibri" })]
      }),

      // Bottom line box
      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [9360],
        rows: [new TableRow({
          children: [new TableCell({
            borders: {
              top: { style: BorderStyle.SINGLE, size: 12, color: GOLD },
              bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD },
              left: { style: BorderStyle.SINGLE, size: 12, color: GOLD },
              right: { style: BorderStyle.SINGLE, size: 12, color: GOLD }
            },
            width: { size: 9360, type: WidthType.DXA },
            shading: { fill: LIGHT_BG, type: ShadingType.CLEAR },
            margins: { top: 200, bottom: 200, left: 240, right: 240 },
            children: [
              new Paragraph({
                spacing: { after: 100 },
                children: [new TextRun({ text: "THE BOTTOM LINE", bold: true, size: 18, color: GOLD, font: "Calibri", characterSpacing: 40 })]
              }),
              new Paragraph({
                spacing: { after: 80 },
                children: [
                  new TextRun({ text: "Injectable Boost ", bold: true, size: 20, font: "Calibri" }),
                  new TextRun({ text: "gets people in the door.", size: 20, font: "Calibri" })
                ]
              }),
              new Paragraph({
                children: [
                  new TextRun({ text: "Luxora ", bold: true, size: 20, font: "Calibri" }),
                  new TextRun({ text: "gets people in the door, converts them, retains them, increases their value, and builds a system that scales with you.", size: 20, font: "Calibri" })
                ]
              })
            ]
          })]
        })]
      }),

      // Footer
      new Paragraph({ spacing: { before: 200 }, children: [new TextRun({ text: "" })] }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "theluxoracollective.co", size: 18, color: GOLD, font: "Calibri", bold: true })]
      }),
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/mnt/user-data/outputs/Luxora_vs_Injectable_Boost.docx", buffer);
  console.log("Created successfully");
});

